        <a className="fw-tbtn" href={`?lens=spatial&view=parameters&pmodel=${link.data.local_model_id}&pblock=${block}&pkind=mlp&punit=${unit}`}>打开同一模型的完整参数切片</a><details><summary>全部原生坐标/单元贡献与来源</summary><pre className="v8-artifact-json">{JSON.stringify(link.data,null,2)}</pre></details></>}
    </>}
    {tab==='output'&&<><p>完整前缀的实际下一token分布（前12项展示）</p><table className="v6-table"><thead><tr><th>token</th><th>概率</th></tr></thead><tbody>{d.output_top.map(x=><tr key={x.token_id}><td>{x.text} / {x.token_id}</td><td>{num(x.probability)}</td></tr>)}</tbody></table><p className="v8-note">此表是模型实测输出。上方局部计算关联不是一个已经能独立替代原模型的图谱预测器。</p></>}
  </section></div></>}
  </div>;
}

import { useState } from 'react';
import { useApi } from '../app/rdc_fusion/api.js';
import { Empty } from '../app/rdc_fusion/ui.jsx';
import { orderedStages } from './researchFragmentUtil.js';
import ResearchInterventionReport from './ResearchInterventionReport.jsx';
import DatasetAtlasPlan from './DatasetAtlasPlan.jsx';
import ResearchCatalog from './ResearchCatalog.jsx';

function Workpackage({w,onGo,childRuns=[]}){
  const [expanded,setExpanded]=useState(new URLSearchParams(window.location.search).get('run')===w.body.run_id);
  const report=w.body.stages?.registration_validated?.report_sha256;
  const datasetPlan=w.body.stages?.dataset_atlas_plan?.plan_sha256;
  return <details open={expanded} onToggle={e=>setExpanded(e.currentTarget.open)}>
    <summary>{w.body.title||w.body.run_id}</summary>
    <p className="v8-note">{w.body.run_id} · 更新于 {new Date(w.body.updated_at*1000).toLocaleString()}</p>
    <div className="v8-workpackage-stages">{orderedStages(w.body.stages).map(([k,s])=><span key={k}>
      <b>{({freeze:'冻结材料',registry:'数据与图谱登记',native_audit:'生成全场审计',ai_review:'外部AI盲评',pilot:'行为试跑',collection:'原场采集',intervention:'预注册组干预',interface:'统一采集接口',calibration:'行为校准',prediction:'未见组合预测',native_mlp_plan:'MLP主线规划',discovery:'候选发现',registration_discovery:'登记观察',validation:'留出验证',capability:'能力保持',registration_validated:'登记修订',client_acceptance:'客户端回查',dataset_atlas_plan:'数据与图谱方案'})[k]||k}</b>
      {s.state==='not_supported'&&s.baseline_gate===false?'△ 测量门未通过':({done:'✓ 已完成',not_tested:'未测试',partial:'部分已完成',running:'执行中',ready:'已冻结，待执行',proposed:'方案待实施',not_supported:'△ 未支持',behavior_failed:'△ 行为门失败',noninferior:'✓ 非劣效通过',inferior:'△ 超过允许损失',inconclusive:'△ 尚未证实'})[s.state]||s.state}
    </span>)}</div>
    {expanded&&report&&<ResearchInterventionReport sha={report}/>}
    {expanded&&datasetPlan&&<DatasetAtlasPlan sha={datasetPlan} implementation={w.body.stages.dataset_atlas_plan.state==='partial'}/>}
    {expanded&&childRuns.length>0&&<details><summary>前置校准与试跑（{childRuns.length}）</summary>{childRuns.map(c=><Workpackage key={c.sha} w={c} onGo={onGo}/>)}</details>}
    <button className="fw-tbtn" onClick={()=>onGo('route',null,null,{rtab:'rules'})}>查看拼图与证据</button>
  </details>;
}

export default function ResearchExecution({ plan=false,onGo }){
  const tasks=useApi(plan?null:'/api/tasks',{online:true});
  const packages=useApi('/api/research-library/workpackages');
  const allPackages=packages.data?.workpackages||[];
  const roots=allPackages.filter(w=>!allPackages.some(p=>p!==w&&p.body.run_id===w.body.parent_run_id&&!p.body.parent_run_id));
  return <div className="v8-route"><section className="v8-card"><h2>{plan?'整体图谱研究路线':'执行与审计'}</h2><p className="v8-note">统一材料与行为门 → 全层长文本采集 → 原生单元/Head候选 → 参数路径与干预 → 未见组合预测 → 跨模型复现。每轮产物持续进入证据库，失败和未解释区域也保留。</p></section>
    <div className="v8-direction-cards">{[['材料与测量','冻结实体、属性、角色、语境及语法文法，512/1024/2048 token面板按模型试跑校准。'],['计算图谱','保留完整坐标与MLP阵列，分别记录观察关联、留出复现、参数来源、干预和反例。'],['留出与复算','依次Qwen3-4B、GLM4-9B、Qwen3-14B，CUDA bf16。独立内容家族留出，不跨快照/精度合并。']].map(([t,p])=><section className="v8-card" key={t}><h3>{t}</h3><p className="v8-note">{p}</p></section>)}</div>
    <section className="v8-card"><div className="v6-toolbar"><button className="fw-tbtn" onClick={()=>onGo('catalog')}>任务与数据</button><button className="fw-tbtn" onClick={()=>onGo('route',null,null,{rtab:'rules'})}>持续研究库与证据</button><button className="fw-tbtn" onClick={()=>onGo('config',null,null,{csec:'account'})}>贡献算力 / 节点托管</button></div></section>
    <ResearchCatalog/>
    <section className="v8-card"><div className="v6-toolbar"><h3>实际研究工作包</h3><button className="fw-tbtn" onClick={packages.reload}>刷新工作包</button></div><p className="v8-note">阶段记录来自研究生产者，执行结束不表示假设成立；离线客户端更新数据包后查看最新状态。</p>
      {packages.error?<Empty>{packages.error}</Empty>:!packages.data?<Empty>读取工作包…</Empty>:!allPackages.length?<Empty>尚无已登记工作包。</Empty>:roots.map(w=><Workpackage key={w.sha} w={w} onGo={onGo} childRuns={allPackages.filter(c=>c.body.parent_run_id===w.body.run_id&&c!==w)}/>)}
    </section>
    {!plan&&<section className="v8-card"><div className="v6-toolbar"><h3>真实调度队列</h3><button className="fw-tbtn" onClick={tasks.reload}>刷新队列</button></div>{tasks.error?<Empty>{tasks.error}</Empty>:!tasks.data?<Empty>读取…</Empty>:<><div className="v8-library-stats">{[['queued','排队'],['claimed','执行中'],['done','已完成'],['failed','失败']].map(([k,t])=><span key={k}><b>{tasks.data.stats?.[k]||0}</b>{t}</span>)}</div><p className="v8-note">状态时间 {new Date(tasks.data.server_time*1000).toLocaleString()}；完成表示执行结束，研究证据另行审计。</p><details><summary>当前任务与最近记录</summary><table className="v6-table"><thead><tr><th>任务 / 模板</th><th>节点</th><th>状态</th><th>结果哈希</th></tr></thead><tbody>{[...(tasks.data.queued||[]).map(r=>({...r,status:'queued'})),...(tasks.data.active||[]).map(r=>({...r,status:'claimed'})),...(tasks.data.recent||[])].map(r=><tr key={r.task_id}><td>{r.task_id}<small>{r.tm_id}</small></td><td>{r.node_name||'—'}</td><td>{r.status}</td><td>{r.result_sha?.slice(0,12)||'—'}</td></tr>)}</tbody></table></details></>}</section>}
  </div>;
}
